const crypto = require('crypto');

const submitted = String($('Webhook').first().json.body.code || '').trim();
const row = $input.first().json || {};

const pepper = $env.DEMO_CODE_PEPPER;
if (!pepper) throw new Error('DEMO_CODE_PEPPER is not set on the n8n container');

// No unconsumed code for this address at all: alwaysOutputData gave us an
// empty item rather than ending the execution silently.
if (!row.code_id) {
  return [{ json: { ok: false, code_id: null } }];
}

const expected = crypto.createHmac('sha256', pepper).update(submitted).digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(String(row.code_hash || ''));

// Length first: timingSafeEqual throws on a mismatch. Both sides are fixed
// width hex, so the length is not a secret.
const macOk = a.length === b.length && crypto.timingSafeEqual(a, b);

const ok = macOk && row.not_expired === true && Number(row.attempts) < 5;

return [{ json: { ok, code_id: row.code_id } }];

// ---8<--- SHARED START ---8<---
// Copied verbatim into the "Verify Token" Code node in
// workflows/demo-verify-session.json and the "Sign Token" Code node in
// workflows/demo-verify-code.json.
// tests/demo-workflow.test.js fails if they drift apart.
//
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n container.

const crypto = require('crypto');

function base64url(buf) {
  return Buffer.from(buf)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

// A real token is ~94 chars (uuid + '.' + ms timestamp + '.' + base64url mac).
// The cap is generous but bounded: sessionId is attacker-controlled, and
// without it an arbitrarily large string reaches the HMAC.
const MAX_TOKEN_LENGTH = 512;

function signToken(sessionId, expiresAtMs, secret) {
  if (!sessionId) throw new Error('signToken requires a sessionId');
  if (!secret) throw new Error('signToken requires a secret');
  if (typeof secret !== 'string' && !Buffer.isBuffer(secret)) {
    throw new Error('signToken requires a string or Buffer secret');
  }
  // Postgres `extract(epoch from ...) * 1000` yields a NUMERIC with a
  // fractional part, and String(1788695089121.642) is "1788695089121.642".
  // verifyToken requires /^\d+$/ on the expiry segment, so a float here mints
  // a token that can never verify -- a silent, and very confusing, failure.
  // Fail at the point of the mistake instead.
  if (!Number.isInteger(expiresAtMs)) {
    throw new Error('signToken requires an integer expiresAtMs (got ' + expiresAtMs + ')');
  }
  const payload = String(sessionId) + '.' + String(expiresAtMs);
  const mac = crypto.createHmac('sha256', secret).update(payload).digest();
  return payload + '.' + base64url(mac);
}

function verifyToken(token, secret, nowMs) {
  if (typeof token !== 'string') return null;
  // A truthy non-string secret would throw inside createHmac rather than
  // reject here -- in a Code node that is a 500 instead of a clean refusal.
  if (typeof secret !== 'string' && !Buffer.isBuffer(secret)) return null;
  if (!secret.length) return null;
  if (token.length > MAX_TOKEN_LENGTH) return null;

  const parts = token.split('.');
  if (parts.length !== 3) return null;

  const sessionId = parts[0];
  const expiresRaw = parts[1];
  const providedMac = parts[2];
  if (!sessionId || !expiresRaw) return null;

  // Reject before doing crypto work on obviously bad input.
  if (!/^\d+$/.test(expiresRaw)) return null;
  const expiresAtMs = Number(expiresRaw);
  if (!Number.isFinite(expiresAtMs)) return null;

  const expectedMac = base64url(
    crypto.createHmac('sha256', secret).update(sessionId + '.' + expiresRaw).digest()
  );

  const a = Buffer.from(providedMac);
  const b = Buffer.from(expectedMac);
  // timingSafeEqual throws on a length mismatch, so check length first.
  // Length is not a secret -- the MAC is a fixed width.
  if (a.length !== b.length) return null;
  if (!crypto.timingSafeEqual(a, b)) return null;

  // Signature is good; now check the claim it protects.
  if (expiresAtMs <= nowMs) return null;

  return { sessionId: sessionId, expiresAtMs: expiresAtMs };
}

// --- node glue below the shared block -------------------------------------
const row = $input.first().json || {};
if (!row.session_id) {
  // The code was already consumed by a concurrent request. Fail closed --
  // but RETURN rather than throw, so this node's error output carries only
  // real misconfiguration. A missing DEMO_SESSION_SECRET below would
  // otherwise be indistinguishable from a replayed code, and would 401
  // every visitor on the site while alerting nobody.
  return [{ json: { ok: false } }];
}

const secret = $env.DEMO_SESSION_SECRET;
if (!secret) throw new Error('DEMO_SESSION_SECRET is not set on the n8n container');

// expires_ms arrives floored from SQL; Number() keeps signToken's integer
// guard satisfied whether the driver hands back a bigint as string or number.
const expiresMs = Number(row.expires_ms);
const token = signToken(row.session_id, expiresMs, secret);

return [{ json: { ok: true, session_id: row.session_id, token, expires_ms: expiresMs } }];

// The caller already has its response; this only fails the execution
// so that settings.errorWorkflow is invoked. See raiseForAlertNode.
const item = $input.first().json || {};
// The error item's shape varies by node type, so read it defensively
// and fall back to naming the stage. The alert email links to this
// execution, where the untruncated error already is.
const raw = item.error;
const detail = (raw && raw.message) || (typeof raw === 'string' ? raw : '') ||
  'see the failed node in this execution';
throw new Error("demo-verify-code could not sign a session token" + ': ' + detail);
